;
; XLIN2A -- docs/bios/PINLIN.md round 2 (2026-11-17). GENERATED by probes/bios/spec/xlin2_gen.py (--gen), whose
; docstring documents the calls, the setup and the record; the same module decodes the run.
; Run: python3 -u probes/bios/biosl_run.py probes/bios/spec/xlin2a.asm --row nodisk
;
; CLEAN-ROOM: 100% own code; only published BIOS entries and work-area cells; VRAM through RDVRM / WRTVRM.
;
; @cap C000
; @type-ready \rQ\rQ\rR\rQ\rQ\r
; @timeout 60

RDVRM   equ     $004A
WRTVRM  equ     $004D
INITXT  equ     $006C
LINL40  equ     $F3AE
CSRY    equ     $F3DC
CSRX    equ     $F3DD
CNSDFG  equ     $F3DE
CSRSW   equ     $FCA9
BUF     equ     $F55E
AUTFLG  equ     $F6AA
NB      equ     16
NR      equ     12

DONE    equ     $C000
CAP     equ     $C001
ptr     equ     $EF00
crow    equ     $EF02
rHL     equ     $EF04
rF      equ     $EF06
cnum    equ     $EF07

                org     $4000
                db      "AB"
                dw      init, 0, 0, 0
                ds      6, 0

init:
                ld      hl, CAP
                ld      de, CAP+1
                ld      bc, $FE
                ld      (hl), 0
                ldir
                xor     a
                ld      (CNSDFG), a
                ld      (CSRSW), a
                ld      (cnum), a
                ld      a, 40
                ld      (LINL40), a
                call    INITXT
                ld      a, 1                    ; KEYREADY: the harness types the burst now (@type-ready)
                ld      ($C100), a
                ld      hl, CAP
                ld      (ptr), hl
                ld      ix, calls
c_lp:
                ld      a, (ix+0)
                cp      $FF
                jp      z, c_done
                ld      a, (ix+3)
                ld      (crow), a
                ld      a, (ix+4)
                ld      (AUTFLG), a
                ld      hl, BUF
                ld      b, 40
c_bf:
                ld      (hl), $FF
                inc     hl
                djnz    c_bf
                ; pre-written text: (ix+5..6) -> a list of (column, length, bytes...), 0 ends
                ld      l, (ix+5)
                ld      h, (ix+6)
c_pre:
                ld      a, (hl)
                or      a
                jr      z, c_go
                push    hl
                call    rowcol                  ; DE := the name-table address of (crow, A)
                pop     hl
                inc     hl
                ld      b, (hl)
                inc     hl
c_pw:
                ld      a, (hl)
                push    hl
                push    de
                ex      de, hl
                call    WRTVRM
                pop     de
                pop     hl
                inc     de
                inc     hl
                djnz    c_pw
                jr      c_pre
c_go:
                ld      a, (ix+2)
                ld      (CSRX), a
                ld      a, (crow)
                ld      (CSRY), a
                ld      l, (ix+0)
                ld      h, 0
                push    ix
                call    jphl
                push    af
                pop     bc
                ld      (rHL), hl
                ld      a, c
                ld      (rF), a
                pop     ix
                ld      a, (cnum)
                inc     a
                ld      (cnum), a
                call    emit                    ; the call's own STAGE byte
                ld      hl, (rHL)
                ld      a, l
                call    emit
                ld      a, h
                call    emit
                ld      a, (rF)
                call    emit
                ld      a, (CSRX)
                call    emit
                ld      a, (CSRY)
                call    emit
                ld      hl, BUF
                ld      b, NB
c_rb:
                ld      a, (hl)
                call    emit
                inc     hl
                djnz    c_rb
                ld      b, NR
                ld      a, b
                or      a
                jr      z, c_nr
                push    bc
                ld      a, 1
                call    rowcol
                pop     bc
                ex      de, hl
c_rr:
                push    bc
                push    hl
                call    RDVRM
                call    emit
                pop     hl
                pop     bc
                inc     hl
                djnz    c_rr
c_nr:
                ld      de, 7
                add     ix, de
                jp      c_lp
c_done:
                ld      a, $C3
                call    emit
                ld      a, $A5
                ld      (DONE), a
halt_lp:
                jr      halt_lp

jphl:
                jp      (hl)

; rowcol -- DE := the name-table address of row (crow), column A (both 1-based), 40 columns
rowcol:
                dec     a
                ld      e, a
                ld      d, 0
                ld      a, (crow)
                ld      b, a
                ld      hl, 40
r_lp:
                dec     b
                jr      z, r_done
                ex      de, hl
                add     hl, de
                ex      de, hl
                jr      r_lp
r_done:
                ret

emit:
                push    hl
                ld      hl, (ptr)
                ld      (hl), a
                inc     hl
                ld      (ptr), hl
                pop     hl
                ret

; per call: entry (low byte; the high is 0), unused, CSRX, CSRY, AUTFLG, the pre-written list's address; $FF ends
calls:
                db      $B1, 0, 1, 3, $00
                dw      pre0
                db      $B1, 0, 4, 5, $00
                dw      pre1
                db      $B1, 0, 6, 7, $00
                dw      pre2
                db      $B4, 0, 4, 9, $00
                dw      pre3
                db      $AE, 0, 4, 11, $FF
                dw      pre4
                db      $B1, 0, 4, 13, $FF
                dw      pre5
                db      $FF
pre0:
                db      1, 3, $58, $59, $5A
                db      0
pre1:
                db      1, 5, $58, $59, $5A, $57, $56
                db      0
pre2:
                db      1, 3, $58, $59, $5A
                db      0
pre3:
                db      1, 3, $58, $59, $5A
                db      0
pre4:
                db      1, 3, $58, $59, $5A
                db      0
pre5:
                db      1, 3, $58, $59, $5A
                db      0
